/**
 * A character as stored (the sheet jsonb, plus xp and level_applied). Levels come from XP; levelApplied is the
 * level the sheet has actually been built to (P2-6). When XP has gone past it, level-ups are pending, and the
 * sheet's numbers stay at the applied level until the level-up flow builds the new one.
 */
export interface CharacterSheet {
  name: string;
  species: string;
  className: string;
  background: string;
  alignment: string;
  xp: number;
  /** The level the sheet has been built to; without it, the level from XP (Phase 1 sheets). */
  levelApplied?: number;
  /** Weapon training (P2-7, P2-9); without it, every item weapon counts as proficient (Phase 1 sheets). */
  weaponProficiencies?: WeaponTraining[];
  abilityScores: AbilityScores;
  skillProficiencies: SkillKey[];
  expertise: SkillKey[];
  saveProficiencies: Ability[];
  hp: { max: number; current: number; temp: number };
  hitDice: { die: string; total: number; spent: number };
  /** Base walking speed in feet, as entered (species-driven speed comes with the creation wizard in Phase 2). */
  speed: number;
  armor: SheetArmor | null;
  shield: boolean;
  weapons: SheetWeapon[];
  equipment: string[];
  inspiration: boolean;
  // P2-9: what the creation wizard records besides the numbers (shown on the Details and Spells tabs, P2-11)
  /** Size chosen from the species' options. */
  size?: 'tiny' | 'small' | 'medium' | 'large';
  originFeat?: string;
  toolProficiency?: string;
  spells?: { cantrips: string[]; prepared: string[]; spellbook?: string[] };
  details?: CharacterDetails;
}

/** Weapon training: Simple, all Martial, or only Martial weapons with the Light or Finesse property (Monk, Rogue). */
export type WeaponTraining = 'simple' | 'martial' | 'martial-light' | 'martial-finesse';

